	@Test
	void readsThatFoundNothingAreKeptAsTheDigestsOfTheirPosteriorKeysAndChargedAsSuch(@TempDir Path directory)
			throws Exception {
		Fixture fixture = new Fixture(directory, "encoding");
		LogicalLearningKey logical = logical("encoded");
		PhysicalEventKey event = event("encoded-source", "current");
		Runnable reads = () -> {
			fixture.logicalRead(logical, APPLICABILITY, ROWS);
			fixture.physicalRead(logical, PHYSICAL, APPLICABILITY, RESULT);
			fixture.physicalRead(logical, PHYSICAL, APPLICABILITY, SOURCE);
			fixture.eventRead(event, PHYSICAL, APPLICABILITY, RESULT);
			fixture.stats.exactCardinalityFact(logical, APPLICABILITY);
		};

		Log compact = record(true, reads);
		Log full = record(false, reads);

		List<Read> decoded = compact.reads();
		assertAll(
				() -> assertEquals(5, compact.readCount()),
				() -> assertEquals(5, compact.digestGroupCount(),
						"one witness group per distinct posterior key: the source-rows read has its own"),
				() -> assertEquals(5, compact.groupCount(), "no key group keeps keys"),
				() -> assertWitness(decoded.get(0), LmdbPlanningReadLog.LOGICAL, ROWS,
						digest(out -> LearningKeyDigests.logicalPosterior(logical, APPLICABILITY, out))),
				() -> assertWitness(decoded.get(1), LmdbPlanningReadLog.PHYSICAL, RESULT,
						digest(out -> LearningKeyDigests.physicalPosterior(logical, PHYSICAL, APPLICABILITY, out))),
				() -> assertWitness(decoded.get(2), LmdbPlanningReadLog.PHYSICAL, SOURCE,
						digest(out -> LearningKeyDigests.physicalPosterior(logical, PHYSICAL.sourceRowsPredictor(),
								APPLICABILITY, out))),
				() -> assertWitness(decoded.get(3), LmdbPlanningReadLog.EVENT, RESULT,
						digest(out -> LearningKeyDigests.eventPosterior(event, PHYSICAL, APPLICABILITY, null, out))),
				() -> assertEquals(LmdbPlanningReadLog.EXACT_FACT, decoded.get(4).kind()),
				() -> assertTrue(decoded.get(4).compact()),
				() -> assertEquals(0, decoded.get(4).values().length, "the NaN of a fact witness is implied"),
				() -> assertEquals(LmdbPlanningReadLog.LOG_BYTES + 5L * LmdbPlanningReadLog.DIGEST_GROUP_BYTES
						+ 5L * LmdbPlanningReadLog.READ_BYTES, compact.retainedBytes(),
						"a witness log charges its groups' digests and its reads, and no key"),
				() -> assertEquals(0, full.digestGroupCount()),
				() -> assertEquals(4, full.groupCount()),
				() -> assertTrue(full.retainedBytes() > compact.retainedBytes() + 2_000L,
						"the full log keeps the keys: " + full.retainedBytes()),
				() -> assertEquals(full.count(LmdbPlanningReadLog.PHYSICAL),
						compact.count(LmdbPlanningReadLog.PHYSICAL)),
				() -> assertEquals(2, compact.count(LmdbPlanningReadLog.ABSENT_PHYSICAL)),
				() -> assertEquals(full.count(LmdbPlanningReadLog.EXACT_FACT),
						compact.count(LmdbPlanningReadLog.EXACT_FACT)),
				() -> assertEquals(Verdict.IDENTICAL, replay(compact)),
				() -> assertEquals(Verdict.IDENTICAL, replay(full)));
	}

	@Test
	void aKeyGroupWithAReadThatIsNotAWitnessKeepsItsKeysForAllItsReads(@TempDir Path directory) throws Exception {
		LmdbOperatorFeedbackStats stats = new Fixture(directory, "mixed").stats;
		LogicalLearningKey logical = logical("mixed");
		FrontierLearningModel.DimensionEstimate estimate = new FrontierLearningModel.DimensionEstimate(12.0d, 6.0d,
				24.0d, 0.25d, 0.0625d, 0.125d, 16.0d, 4L, 0L, 0L);

		Log mixed = record(true, () -> {
			LmdbPlanningReadLog.model(stats, LmdbPlanningReadLog.PHYSICAL, logical, PHYSICAL, APPLICABILITY, SEEKS,
					FEATURES, PREDICTED, decision(null), true);
			LmdbPlanningReadLog.model(stats, LmdbPlanningReadLog.PHYSICAL, logical, PHYSICAL, APPLICABILITY, RESULT,
					FEATURES, PREDICTED, decision(estimate), false);
		});
		Log witnessOnly = record(true, () -> LmdbPlanningReadLog.model(stats, LmdbPlanningReadLog.PHYSICAL, logical,
				PHYSICAL, APPLICABILITY, SEEKS, FEATURES, PREDICTED, decision(null), true));
		Log notTold = record(true, () -> LmdbPlanningReadLog.model(stats, LmdbPlanningReadLog.PHYSICAL, logical,
				PHYSICAL, APPLICABILITY, SEEKS, FEATURES, PREDICTED, decision(null), false));

		assertAll(
				() -> assertEquals(0, mixed.digestGroupCount(), "the key group is kept whole"),
				() -> assertSame(logical, mixed.reads().get(0).first()),
				() -> assertFalse(mixed.reads().get(0).compact()),
				() -> assertTrue(mixed.reads().get(0).predictedFinite(), "the flags survive"),
				() -> assertEquals(1, witnessOnly.digestGroupCount()),
				() -> assertTrue(witnessOnly.reads().get(0).predictedFinite()),
				() -> assertEquals(0, notTold.digestGroupCount(),
						"a read the owner did not report below the minimum is kept with its keys"));
	}

