	@Test
	void aModelWitnessReplaysIdenticalBelowTheMinimumAndChangedFromIt(@TempDir Path directory) throws Exception {
		Fixture fixture = new Fixture(directory, "minimum");
		fixture.calibrate(APPLICABILITY);
		LogicalLearningKey logical = logical("minimum-logical");
		LogicalLearningKey physical = logical("minimum-physical");
		PhysicalEventKey event = event("minimum-source", "current");
		Runnable logicalRead = () -> fixture.logicalRead(logical, APPLICABILITY, ROWS);
		Runnable physicalRead = () -> fixture.physicalRead(physical, PHYSICAL, APPLICABILITY, RESULT);
		Runnable eventRead = () -> fixture.eventRead(event, PHYSICAL, APPLICABILITY, RESULT);
		Log[] compact = { record(true, logicalRead), record(true, physicalRead), record(true, eventRead) };
		Log[] full = { record(false, logicalRead), record(false, physicalRead), record(false, eventRead) };
		byte[] kinds = { LmdbPlanningReadLog.LOGICAL, LmdbPlanningReadLog.PHYSICAL, LmdbPlanningReadLog.EVENT };
		for (Log log : compact) {
			assertEquals(1, log.digestGroupCount(), "COVERAGE_PREREQUISITE: recorded as a witness");
		}

		for (int taught = 1; taught <= MINIMUM; taught++) {
			fixture.teachLogical(logical, APPLICABILITY, 1, 7L);
			fixture.teachPhysical(physical, PHYSICAL, APPLICABILITY, 1, 7L, Double.NaN);
			fixture.teachEvent(event, PHYSICAL, APPLICABILITY, 1, 7L);
			boolean reached = taught == MINIMUM;
			List<FrontierLearningModel.DimensionDecision> decisions = List.of(
					fixture.logicalRead(logical, APPLICABILITY, ROWS),
					fixture.physicalRead(physical, PHYSICAL, APPLICABILITY, RESULT),
					fixture.eventRead(event, PHYSICAL, APPLICABILITY, RESULT));
			for (int population = 0; population < 3; population++) {
				String context = "population " + population + " after " + taught + " observations";
				assertEquals(reached, decisions.get(population).estimate() != null,
						"COVERAGE_PREREQUISITE: the gate applies from the minimum on: " + context);
				LmdbPlanningReadLog.ReplayResult compactResult = compact[population].replayAgainstOwners(TOLERANCE,
						() -> {
						});
				LmdbPlanningReadLog.ReplayResult fullResult = full[population].replayAgainstOwners(TOLERANCE, () -> {
				});
				assertEquals(reached ? Verdict.CHANGED : Verdict.IDENTICAL, fullResult.verdict(), context);
				assertEquals(fullResult.verdict(), compactResult.verdict(), context);
				if (reached) {
					assertEquals(kinds[population], compactResult.kind(), "reported as the read it stands for");
				}
			}
		}
	}

	@Test
	void aSourceRowsWitnessFollowsTheResidualTheModelLooksTheCellUpBy(@TempDir Path directory) throws Exception {
		Fixture fixture = new Fixture(directory, "source");
		fixture.calibrate(APPLICABILITY);
		LogicalLearningKey logical = logical("source-rows");
		Runnable sourceRead = () -> fixture.physicalRead(logical, PHYSICAL, APPLICABILITY, SOURCE);
		Runnable resultRead = () -> fixture.physicalRead(logical, PHYSICAL, APPLICABILITY, RESULT);
		Log sourceCompact = record(true, sourceRead);
		Log sourceFull = record(false, sourceRead);
		Log resultCompact = record(true, resultRead);
		Log resultFull = record(false, resultRead);

		// Without a source-rows prediction the observation reaches only the residual's own cell.
		fixture.teachPhysical(logical, PHYSICAL, APPLICABILITY, MINIMUM, 7L, Double.NaN);
		Verdict[] rawTaught = { replay(sourceCompact), replay(sourceFull), replay(resultCompact),
				replay(resultFull) };
		fixture.teachPhysical(logical, PHYSICAL, APPLICABILITY, MINIMUM, 7L, 10.0d);
		Verdict[] sourceTaught = { replay(sourceCompact), replay(sourceFull) };

		assertAll(
				() -> assertNotNull(fixture.physicalRead(logical, PHYSICAL, APPLICABILITY, RESULT).estimate(),
						"COVERAGE_PREREQUISITE: the residual's cell estimates"),
				() -> assertNotNull(fixture.physicalRead(logical, PHYSICAL, APPLICABILITY, SOURCE).estimate(),
						"COVERAGE_PREREQUISITE: the source-rows cell estimates"),
				() -> assertEquals(Verdict.IDENTICAL, rawTaught[1], "COVERAGE_PREREQUISITE: full source read"),
				() -> assertEquals(rawTaught[1], rawTaught[0],
						"the source-rows witness is not the residual's own cell"),
				() -> assertEquals(Verdict.CHANGED, rawTaught[3]),
				() -> assertEquals(rawTaught[3], rawTaught[2]),
				() -> assertEquals(Verdict.CHANGED, sourceTaught[1]),
				() -> assertEquals(sourceTaught[1], sourceTaught[0]));
	}

