	@Test
	void anExactFactWitnessReplaysIdenticalUntilAFactUnderItsKeyAnswers(@TempDir Path directory) throws Exception {
		Fixture fixture = new Fixture(directory, "facts");
		LogicalLearningKey logical = logical("fact");
		Runnable read = () -> fixture.stats.exactCardinalityFact(logical, APPLICABILITY);
		Log absentCompact = record(true, read);
		Log absentFull = record(false, read);
		Verdict beforeFact = replay(absentCompact);

		fixture.publishFact(logical, APPLICABILITY, 7L);
		Verdict[] afterFact = { replay(absentCompact), replay(absentFull) };
		Log answered = record(true, read);

		fixture.liveStamp.set(1L);
		Log staleCompact = record(true, read);
		Log staleFull = record(false, read);
		Verdict[] whileStale = { replay(staleCompact), replay(staleFull) };
		fixture.liveStamp.set(0L);
		Verdict[] currentAgain = { replay(staleCompact), replay(staleFull) };

		assertAll(
				() -> assertEquals(1, absentCompact.digestGroupCount()),
				() -> assertEquals(Verdict.IDENTICAL, beforeFact),
				() -> assertEquals(Verdict.CHANGED, afterFact[1]),
				() -> assertEquals(afterFact[1], afterFact[0]),
				() -> assertEquals(0, answered.digestGroupCount(), "a read that answered keeps its keys"),
				() -> assertEquals(7.0d, answered.reads().get(0).values()[0], 0.0d),
				() -> assertEquals(1, staleCompact.digestGroupCount(), "a stale fact reads NaN: a witness"),
				() -> assertEquals(Verdict.IDENTICAL, whileStale[1]),
				() -> assertEquals(whileStale[1], whileStale[0]),
				() -> assertEquals(Verdict.CHANGED, currentAgain[1], "a stale fact whose stamp matches again"),
				() -> assertEquals(currentAgain[1], currentAgain[0]));
	}

